#include <vector>
#include <omp.h>

void reversePrefixSum(std::vector<int> const& x, std::vector<int> &output) {
    const std::size_t n = x.size();
    output.resize(n);
    if (n == 0) return;

    int nthreads = 1;
    std::vector<long long> chunkSums;
    std::vector<long long> offsets;

    #pragma omp parallel
    {
        int tid = omp_get_thread_num();
        int nt  = omp_get_num_threads();

        #pragma omp single
        {
            nthreads = nt;
            chunkSums.assign(nthreads, 0LL);
            offsets.assign(nthreads, 0LL);
        }

        std::size_t start = (n * static_cast<std::size_t>(tid)) / static_cast<std::size_t>(nt);
        std::size_t end   = (n * static_cast<std::size_t>(tid + 1)) / static_cast<std::size_t>(nt);

        long long localSum = 0;
        for (std::size_t i = start; i < end; ++i) {
            localSum += static_cast<long long>(x[i]);
            output[i] = static_cast<int>(localSum);
        }
        chunkSums[tid] = localSum;

        #pragma omp barrier

        #pragma omp single
        {
            long long running = 0;
            for (int t = 0; t < nthreads; ++t) {
                offsets[t] = running;
                running += chunkSums[t];
            }
        }

        #pragma omp barrier

        long long add = offsets[tid];
        for (std::size_t i = start; i < end; ++i) {
            output[i] = static_cast<int>(static_cast<long long>(output[i]) + add);
        }
    }
}
